from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[2];repo=root.parents[2]
brief=(repo/'ArtHandoff/requests/B04/CODEX_ART_REQUEST.md').read_text(encoding='utf-8-sig')
lock=json.loads((root/'DELIVERABLE_MANIFEST.json').read_text())['styleLock']['promptTemplate']
characters=[('nyxara','slim_staff','slim_staff','slim_staff'),('ashara','heavy_sword','heavy_sword','heavy_shield'),('nerissa','slim_staff','slim_staff','slim_staff'),('voltrix','slim_staff','slim_staff','slim_staff'),('eirwen','heavy_shield','heavy_shield','heavy_hammer'),('kael','slim_sword','slim_sword','slim_staff')]
common='''Use case: stylized-concept. Aetherward production character art. Reference 1 is approved B01/B02 STYLE ATLAS, materials/brushwork/palette only; never reproduce its panels, text or backdrop. Reference 2 CLAY controls exact camera, pose and facing. Any subsequent reference is this hero IDENTITY: preserve face, adult proportions, costume, palette and equipment unless explicitly evolving. Adult heroic 5.5–6 heads tall, NOT chibi. Orthographic view from ABOVE at 38.3 degrees, facing screen-right. Key requirement: bright upper/front material planes plus cool back-right rim #9fe8ff; edge-band mean luminance >=0.30 against dark basalt .16. Make visible silver-grey light-catching outer planes even on dark clothing, directional 2–3px export rim, no uniform outline. Metal, cloth, skin visibly distinct; crisp broad painterly planes; no noisy microtexture. Transparent background, one complete isolated character, NO ground, pedestal, shadow, text, labels or watermark. NO projectile, beam, slash trail, explosion or ground VFX. Small glow confined to equipment, element accents <=20% area. Request native >=1600 square output; NEVER upscale. Full figure must fit icon box: on proportional 400 canvas, x40–360, y82–372, torso x200, head top117–137, feet at372. Guardian width >=1.35x mage, wider rather than taller. Keep long weapons foreshortened to fit the box. Quality judged at 2560x1440.'''
poses={'idle':'Neutral ready stance, centred weight. Match clay idle; entire figure, equipment and both feet visible.','cast':'Clear skill casting key pose: focus/weapon raised, free arm opened, torso lifted about 6%, element accent brightest. Feet/knees retain ground contact. No emitted spell.','attack':'Clear basic strike/release moment toward +X/screen-right; end of weapon swing or staff extension. Hands convincingly grip equipment. Keep torso centred and weapon compact/foreshortened INSIDE icon bounds. No projectile/beam/slash trail.','downed':'Base identity only, collapsed/kneeling defeat pose, head bowed, body low, knee/foot contact at row372. Desaturate about40%. Clay idle controls camera only; override standing pose to a believable kneel.'}
plans=[]
for hero,*builds in characters:
 section=next(s for s in brief.split('#### ') if f'(`{hero}`)' in s)
 lines=section.splitlines();base=next(l.split('- Base design: ',1)[1] for l in lines if l.startswith('- Base design:'))
 designs={'base':base}
 for branch in ['A','B']:designs['evo'+branch]=next(l for l in lines if l.startswith('- evo'+branch+' ='))
 for name,branch,pose in [('idle','base','idle'),('cast','base','cast'),('downed','base','downed'),('evoA','evoA','idle'),('evoA_cast','evoA','cast'),('evoB','evoB','idle'),('evoB_cast','evoB','cast'),('attack','base','attack'),('evoA_attack','evoA','attack'),('evoB_attack','evoB','attack')]:
  build=builds[['base','evoA','evoB'].index(branch)];clay=f'{build}_{pose if pose!="downed" else "idle"}.png'
  refs=[str(root/'source/references/approved_style_atlas.png'),str(repo/'ArtHandoff/requests/pose_refs'/clay)]
  identity=None if name=='idle' else f'{hero}_idle' if pose=='idle' or branch=='base' else f'{hero}_{branch}'
  if identity:refs.append(str(root/f'source/sheets/{identity}.png'))
  prompt=lock+'\n'+common+'\nHERO: '+hero+'\nBASE IDENTITY: '+base+'\nDESIGN: '+designs[branch]+'\nPOSE: '+poses[pose]
  if branch!='base':prompt+='\nEvolution preserves face and palette anchor, changes at least three of silhouette, costume tier, weapon, body element motifs. Do not copy the unchanged base costume.'
  plans.append(dict(id='Heroes/'+hero+'_'+name,prompt=prompt,refs=refs,source=f'source/sheets/{hero}_{name}.png',promptFile=f'source/prompts/{hero}_{name}.json',branch=branch,pose=pose))
 refs=[str(root/'source/references/approved_style_atlas.png'),str(repo/'ArtHandoff/requests/pose_refs'/f'{builds[0]}_idle.png'),str(root/f'source/sheets/{hero}_idle.png')]
 plans.append(dict(id='Portraits/'+hero,prompt=lock+'\nUse case: stylized-concept. Head-and-shoulders portrait of '+hero+' from attached IDENTITY reference3, same face, hood/helm/hair/costume and light. Reference1 approved B01/B02 style atlas only, reference2 clay for matching camera/facing. '+base+'\nSquare portrait, tight head and shoulders composition, dark vignette background, crisp deliberate brushwork and facial planes, no text, no border, no extra object. Native at least768x768. No full-body figure. No projectiles/VFX.',refs=refs,source=f'source/sheets/{hero}_portrait.png',promptFile=f'source/prompts/{hero}_portrait.json',branch='base',pose='portrait'))
(root/'source/generation_plan.json').write_text(json.dumps(plans,indent=2),encoding='utf-8')
print('Planned',len(plans),'separate generation calls with exact identity dependencies and clay references.')
